<script setup lang="ts">
import {ref,computed} from 'vue';
import PmsKanbanCard from './PmsKanbanCard.vue';
const props=defineProps<{data:any;permissions:string[];busy?:boolean;department?:any;projectFilter?:string;workflowFilter?:string;sprintFilter?:string}>();
const emit=defineEmits(['project','workflow','sprint','newSprint','sprintState','workload','create','quickCreate','open','edit','assign','delete','handoff','place','drop','drag']);
const quickTitle=ref(''),quickProject=ref('');const can=(key:string)=>props.permissions.includes('*')||props.permissions.includes(key);
const tasks=(id:number)=>props.data.boardTasks?.filter((t:any)=>t.workflow_column_id===id)||[];
const metrics=computed(()=>props.department?[{key:'projects',label:'Projects',value:props.data.departmentProjects?.length||0},{key:'tasks',label:'Visible tasks',value:props.data.departmentStats?.tasks||0},{key:'backlog',label:'Backlog tasks',value:props.data.departmentStats?.backlog||0},{key:'sprint',label:'Sprint tasks',value:props.data.departmentStats?.sprint||0}]:[{key:'total',label:'All sprints',value:props.data.sprintStats?.total||0},{key:'active',label:'Active',value:props.data.sprintStats?.active||0},{key:'planned',label:'Planned',value:props.data.sprintStats?.planned||0},{key:'completed',label:'Completed',value:props.data.sprintStats?.completed||0}]);
function quick(){if(!quickTitle.value.trim())return;emit('quickCreate',quickTitle.value.trim(),()=>quickTitle.value='',quickProject.value);}
</script>
<template><section class="jira-shell"><div v-if="busy" class="board-loading" role="status"><div class="board-loading-card"><span class="spinner-border spinner-border-sm text-primary" aria-hidden="true"></span>Updating board...</div></div><div class="jira-toolbar mb-3"><div><div class="text-muted small mb-1">{{department?'TEAM SPACE / '+department.dept_name.toUpperCase():'PROJECT / '+data.project?.name?.toUpperCase()}}</div><h3 class="mb-1">{{department?'Department sprint board':'Sprint board'}}</h3><small v-if="department" class="text-muted">Work across {{data.departmentProjects?.length||0}} accessible projects.</small></div><div class="d-flex gap-2 align-items-center flex-wrap"><select v-if="department" aria-label="Board project" class="form-select" :value="projectFilter" @change="emit('project',($event.target as HTMLSelectElement).value)"><option value="">All {{department.dept_name}} work</option><option value="department-backlog">{{department.dept_name}} department backlog</option><option v-for="p in data.departmentProjects" :key="p.id" :value="p.id">{{p.name}} &mdash; project backlog and sprints</option></select><select v-if="data.workflows?.length>1" class="form-select" aria-label="Board workflow" :value="workflowFilter||data.selectedWorkflow?.id" @change="emit('workflow',($event.target as HTMLSelectElement).value)"><option v-for="w in data.workflows" :key="w.id" :value="w.id">{{w.name}}{{w.department?' ? '+w.department.dept_name:''}}</option></select><select aria-label="Board sprint" class="form-select" :value="sprintFilter||data.selectedSprint?.id||(department?'all':'backlog')" @change="emit('sprint',($event.target as HTMLSelectElement).value)"><option v-if="department" value="all">All sprints and backlog</option><option value="backlog">Backlog</option><option v-for="s in data.sprints" :key="s.id" :value="s.id">{{s.name}} &middot; {{s.status.charAt(0).toUpperCase()+s.status.slice(1)}} ({{s.tasks_count||0}})</option></select><button v-if="can('project-edit')&&!department" class="button pms-outline-primary" @click="emit('newSprint')"><i class="ti ti-bolt" aria-hidden="true"></i>New sprint</button><button v-if="can('project-edit')&&!department&&data.selectedSprint" class="button" @click="emit('sprintState')">{{data.selectedSprint.status==='active'?'Complete sprint':'Start sprint'}}</button></div></div><div class="sprint-goal-panel"><i class="ti ti-target sprint-goal-icon" aria-hidden="true"></i><div class="sprint-goal-content"><div class="sprint-goal-label">{{data.selectedSprint?'Sprint goal':department?'Department overview':'Backlog'}}</div><div class="sprint-goal-text">{{data.selectedSprint?.goal||(data.selectedSprint?'No sprint goal defined.':department?'Showing work across this department. Use the filters to focus the board.':'Tasks not assigned to a sprint.')}}</div></div></div><div class="d-flex gap-2 flex-wrap mb-3 pms-board-metrics"><div v-for="m in metrics" :key="m.key" class="metric-card"><div class="small text-muted">{{m.label}}</div><div class="metric-value" :class="{ 'text-primary':m.key==='active'||m.key==='projects','text-warning':m.key==='planned'||m.key==='backlog','text-success':m.key==='completed'||m.key==='sprint'}">{{m.value}}</div></div><button v-if="!department" class="btn btn-label-secondary ms-auto" @click="emit('workload')"><i class="ti ti-users" aria-hidden="true"></i>Assignee workload</button></div><form v-if="can('task-add')" class="card mb-3 pms-board-quick-create" @submit.prevent="quick"><div class="card-body py-2"><div class="input-group"><span class="input-group-text"><i class="ti ti-plus" aria-hidden="true"></i></span><select v-if="department" v-model="quickProject" aria-label="Quick task project" required class="form-select"><option value="">Select project first...</option><option v-for="p in data.departmentProjects" :key="p.id" :value="p.id">{{p.name}}</option></select><input v-model="quickTitle" required maxlength="255" :placeholder="'Create a task in '+(data.selectedSprint?.name||'Backlog')" aria-label="Quick task title" class="form-control"><button class="button primary" :disabled="busy">Create task</button><button class="button pms-outline-primary" type="button" @click="emit('create')">Full issue</button></div></div></form><div class="jira-board"><section class="jira-column" v-for="column in data.selectedWorkflow?.columns" :key="column.id" @dragover.prevent @drop.prevent="emit('drop',column)"><div class="jira-column-title"><span class="badge" :class="'bg-label-'+column.color">{{column.name}}</span><span class="badge bg-white text-dark">{{tasks(column.id).length}}</span></div><div class="jira-task-list"><PmsKanbanCard v-for="(task,index) in tasks(column.id)" :key="task.id" @dragover.prevent @drop.stop.prevent="emit('drop',column,index)" :task="task" :project-name="data.project?.name" :show-project="!!department" :permissions="permissions" :busy="busy" @open="emit('open',$event)" @edit="emit('edit',$event)" @assign="emit('assign',$event)" @delete="emit('delete',$event)" @handoff="emit('handoff',$event)" @place="emit('place',$event)" @drag="emit('drag',$event)"/><div v-if="!tasks(column.id).length" class="jira-empty">Drop tasks here</div></div></section></div></section></template>
